"""Semantic navy/indigo and high-density Slate-50 light operational design tokens."""
STYLES = r'''
:root{--bg:#0b0f1e;--sunken:#080b16;--surface:#141a2e;--raised:#1b2440;--border:#29324d;--text:#e8ebf5;--muted:#a7b2ca;--primary:#8588ff;--positive:#65d9a3;--negative:#ff8da5;--warning:#f2cb79;--shadow:0 20px 70px #080b16}
body.theme-light{--bg:#f8fafc;--sunken:#f1f5f9;--surface:#ffffff;--raised:#e2e8f0;--border:#cbd5e1;--text:#0f172a;--muted:#475569;--primary:#4f46e5;--positive:#15803d;--negative:#be123c;--warning:#b45309;--shadow:0 20px 60px rgba(15,23,42,.15)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px 'Segoe UI',sans-serif;letter-spacing:0}a{color:var(--primary);text-decoration:none}button,input,select,textarea{font:inherit;color:var(--text);background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:9px 12px;min-height:38px}button,a{cursor:pointer}button:hover{background:var(--raised)}button:disabled{opacity:.5;cursor:not-allowed}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,.table-wrap:focus-visible{outline:2px solid var(--primary);outline-offset:3px}.primary{background:var(--primary);color:#fff;font-weight:700}.icon{width:38px;padding:0;font-size:20px}.badge{font-size:11px;border:1px solid var(--border);padding:5px 8px;border-radius:4px;color:var(--positive)}
#sidebar{position:fixed;inset:0 auto 0 0;width:236px;background:var(--sunken);border-right:1px solid var(--border);padding:24px 15px;display:flex;flex-direction:column;z-index:20;overflow-y:auto}.brand{display:flex;gap:12px;align-items:center;color:var(--text);font-size:22px;font-weight:650;margin-bottom:24px}.brand small{display:block;font-size:9px;color:var(--muted);margin-top:4px}.brand b{background:var(--primary);color:#fff;height:38px;width:38px;display:grid;place-items:center;border-radius:6px}label{display:block;font-size:11px;color:var(--muted)}label input,label select{display:block;margin-top:6px}#tenant{width:100%;font-size:12px;margin-bottom:14px}.nav-group{color:var(--muted);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;margin:18px 10px 6px}.nav-link{display:flex;align-items:center;gap:10px;color:var(--muted);padding:8px 11px;margin:2px 0;border-radius:6px;border-left:2px solid transparent;font-size:13px}.nav-link:hover{background:var(--surface);color:var(--text)}.nav-link.active{background:var(--raised);color:var(--primary);border-left-color:var(--primary);font-weight:600}.nav-icon{width:18px;height:18px;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0}.nav-icon svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}.legacy{margin-top:18px;padding:12px 10px;border-top:1px solid var(--border);font-size:11px;color:var(--muted)}#main{margin-left:236px}header{min-height:66px;border-bottom:1px solid var(--border);display:flex;align-items:center;padding:8px 32px;gap:12px;font-size:12px;color:var(--muted);flex-wrap:wrap}.header-actions{margin-left:auto;display:flex;align-items:center;gap:8px;flex-wrap:wrap}#menu{display:none}main{padding:30px 32px 64px;max-width:1640px;margin:auto}.page-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:24px}.eyebrow{font-size:10px;color:var(--primary);margin-bottom:9px}h1{margin:0;font-size:30px;font-weight:600}h2{font-size:17px;font-weight:600;margin:0}h3{font-size:14px;margin:0 0 15px}p{color:var(--muted);line-height:1.6}.period{display:flex;gap:8px;align-items:end}.period input{width:138px;font-size:12px}.notice{font-size:11px;color:var(--warning);margin-bottom:22px}#error,#draft-error{color:var(--negative);line-height:1.5;padding:12px 0}
.ai-hero{background:radial-gradient(120% 130% at 0% 0%,#5b5ee0 0%,#4f46e5 38%,#43309c 72%,#2e2070 100%);border:1px solid rgba(255,255,255,.18);border-radius:12px;padding:22px 26px;color:#fff;margin-bottom:22px;box-shadow:0 16px 40px rgba(79,70,229,.22)}.ai-hero p{color:#f1f5f9;font-size:14.5px;margin:10px 0 16px}.ai-hero .toolbar button{background:rgba(11,15,30,.55);color:#fff;border-color:rgba(255,255,255,.28);font-size:12px;padding:7px 12px;min-height:34px}.ai-hero .toolbar button:hover{background:rgba(11,15,30,.8)}
.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.kpi{padding:20px;text-align:left;min-height:126px}.kpi small{color:var(--muted);display:block;font-size:12px}.kpi strong{display:block;margin:16px 0 9px;font-size:25px;font-weight:600}.kpi span{color:var(--primary);font-size:11px}.section{margin-top:30px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px;flex-wrap:wrap}.split{display:grid;grid-template-columns:1.45fr 1fr;gap:32px}.chart{height:215px;display:flex;align-items:end;gap:14px;padding-top:20px;border-bottom:1px solid var(--border)}.chart-column{flex:1;height:100%;min-width:0;display:flex;flex-direction:column;justify-content:end;align-items:center;gap:7px}.bars{display:flex;align-items:end;gap:4px;height:175px;width:100%;justify-content:center}.bar{width:min(32px,40%);background:var(--positive);border:0;border-radius:3px 3px 0 0;min-height:2px;padding:0}.bar.out{background:var(--primary)}.chart-label{font-size:10px;color:var(--muted);white-space:nowrap}.legend{font-size:11px;color:var(--muted);margin-top:15px}.stat-row{display:flex;justify-content:space-between;padding:15px 0;border-bottom:1px solid var(--border);gap:15px}.toolbar{display:flex;gap:10px;margin-bottom:18px;align-items:center;flex-wrap:wrap}.toolbar input{flex:1;min-width:160px}.table-wrap{overflow:auto;border:1px solid var(--border);border-radius:6px}table{border-collapse:collapse;width:100%;font-size:12px}th{text-align:left;background:var(--surface);color:var(--muted);font-weight:500;padding:13px 15px;white-space:nowrap}td{padding:14px 15px;border-top:1px solid var(--border);vertical-align:middle;max-width:360px;overflow-wrap:anywhere}.row-link{border:0;background:none;color:var(--primary);padding:0;min-height:24px;text-align:left}.empty{padding:45px 15px;color:var(--muted);text-align:center}.tabs{display:flex;gap:22px;border-bottom:1px solid var(--border);overflow:auto;margin:20px 0}.tabs button{border:0;border-bottom:2px solid transparent;background:none;border-radius:0;color:var(--muted);white-space:nowrap;padding:12px 0}.tabs button.active{color:var(--primary);border-bottom-color:var(--primary)}.facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 30px}.fact{padding:18px 0;border-bottom:1px solid var(--border);min-width:0;overflow-wrap:anywhere}.fact small{display:block;color:var(--muted);font-size:11px;margin-bottom:9px;text-transform:none}.fact strong{font-weight:600}.summary{display:flex;gap:35px;margin:20px 0;flex-wrap:wrap}.summary small{display:block;color:var(--muted);margin-bottom:7px}.summary strong{font-size:22px}.hash{font:11px monospace;overflow-wrap:anywhere}.progress{height:8px;background:var(--raised);border-radius:4px;margin:14px 0;overflow:hidden}.progress-fill{height:100%;background:var(--positive)}.target-form{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.target-form input{width:180px}dialog{width:min(760px,calc(100vw - 30px));max-height:90vh;overflow:auto;background:var(--bg);color:var(--text);border:1px solid var(--border);border-radius:8px;padding:24px;box-shadow:var(--shadow)}dialog::backdrop{background:var(--sunken);opacity:.8}.dialog-foot{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-top:25px;padding-top:18px;border-top:1px solid var(--border)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.form-grid input,.form-grid select,.form-grid textarea{width:100%}.line-grid{display:grid;grid-template-columns:2fr 1fr 1fr 38px;gap:8px;margin:12px 0}.line-grid input,.line-grid select{width:100%;min-width:0}.check{display:flex;gap:10px;align-items:start;color:var(--text);font-size:12px;margin-top:20px}.check input{min-height:0}.result{white-space:pre-wrap;color:var(--muted);font-size:12px;line-height:1.7;overflow-wrap:anywhere}.cmd-list{display:flex;flex-direction:column;gap:6px;margin-top:12px}.cmd-item{display:flex;justify-content:space-between;text-align:left;width:100%}
.chart-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:22px}.chart-card{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:18px 20px}.chart-card h3{margin:0 0 6px;font-size:14px;font-weight:600}.chart-sub{font-size:11px;color:var(--muted);margin-bottom:14px}.hbar-list{display:flex;flex-direction:column;gap:10px}.hbar-row{display:grid;grid-template-columns:minmax(110px,1.2fr) 2fr auto;gap:10px;align-items:center;font-size:12px}.hbar-label{color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.hbar-track{height:12px;background:var(--raised);border-radius:6px;overflow:hidden;display:flex}.hbar-fill{height:100%;border-radius:6px}.hbar-val{font-weight:600;font-size:12px;text-align:right;min-width:82px}.stacked-bar{height:18px;background:var(--raised);border-radius:6px;overflow:hidden;display:flex;margin:10px 0}.stacked-seg{height:100%}.ratio-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin-top:18px}.ratio-card{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:14px}.ratio-card small{display:block;font-size:11px;color:var(--muted);margin-bottom:6px}.ratio-card strong{font-size:19px;font-weight:600;display:block}.ratio-card span{font-size:10px;color:var(--muted)}
@media(max-width:1100px){main{padding:25px 22px}.page-head{flex-direction:column}.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.split,.chart-grid{grid-template-columns:1fr}.facts,.ratio-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:767px){#sidebar{display:none;transform:translateX(-100%)}body.menu-open #sidebar{display:flex;transform:none}#main{margin-left:0}#menu{display:block}header{padding:8px 15px}main{padding:24px 15px}h1{font-size:26px}.period{flex-wrap:wrap;width:100%}.period input{width:125px}.kpi{padding:15px;min-height:118px}.kpi strong{font-size:21px}.facts,.form-grid,.ratio-grid{grid-template-columns:1fr}.hbar-row{grid-template-columns:1fr auto}.hbar-track{grid-column:1/-1}.line-grid{grid-template-columns:1fr 1fr}.line-grid input:first-child{grid-column:1/-1}.dialog-foot{flex-wrap:wrap}.badge{font-size:10px}.summary{gap:20px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
'''
